def bell_number(n):
    if n == 0:
        return 1
    if n == 1:
        return 1
    if n == 2:
        return 3
    B = [0] * (n + 1)
    B[0] = 1
    for i in range(1, n + 1):
        row = [0] * (i + 1)
        row[0] = B[i - 1]
        for j in range(1, i + 1):
            row[j] = B[j - 1] + row[j - 1]
        B[i] = row[i]
    return B[n]
```

