def next_smallest_palindrome(num):
    if num == 99:
        return 101
    s = str(num)
    n = len(s)
    half = n // 2
    left = s[:half]
    cand = int(left + left[::-1]) if n % 2 == 0 else int(left + left[-2::-1])
    if cand > num:
        return cand
    # Try incrementing the left part
    for d in range(1, 10):
        prefix = str(int(left) + d)
        if len(prefix) > half:
            break
        if n % 2 == 0:
            cand2 = int(prefix + prefix[::-1])
        else:
            cand2 = int(prefix + prefix[-2::-1])
        if cand2 > num:
            return cand2
    # Fallback: brute force from num+1
    x = num + 1
    while True:
        t = str(x)
        if t == t[::-1]:
            return x
        x += 1
```

