def next_smallest_palindrome(num):
    if num == 99:
        return 101
    numstr = str(num)
    n = len(numstr)
    half = numstr[:n//2]
    left = int(half)
    right = left
    for _ in range(n//2):
        right = right // 10
    right = int(right)
    for d in range(9, -1, -1):
        cand = left * (10**(n//2)) + d * (10**(n//2 - 1) if n % 2 == 1 else 1) + int(half[::-1])
        if cand > num:
            return cand
    # all digits tried, carry
    return next_smallest_palindrome(left * 10 + 1)
```

