def odd_Equivalent(s,n): 
    if n == 0:
        return s.count('1')
    m = len(s)
    if n >= m:
        n = n % m
    count = 0
    for i in range(m):
        if s[(i + n) % m] == '1':
            count += 1
    return count
```

