def is_majority(arr, n, x):
    if n == 0:
        return False
    i = binary_search_left(arr, 0, n-1, x)
    if i == -1:
        return False
    count = n - i
    return count > n // 2

def binary_search_left(arr, low, high, x):
    ans = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            ans = mid
            high = mid - 1
        elif arr[mid] < x:
