def get_total_number_of_sequences(m, n):
    if n == 0:
        return 1
    if n == 1:
        return m

    dp = [0] * (m + 1)
    dp[0] = 1

    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        for v in range(1, m + 1):
            low = 2 * (v // 2 if v % 2 == 0 else v - 1) // 2  # wrong, fix below
        # Correct logic:
        # For a fixed last element v, previous element p must satisfy: p <= v/2 and p >= 1.
        # So p can be any integer in [1, floor(v/2)].
        # Thus new_dp[v] = sum(dp[p] for p in 1..floor(v/2))
        # We can compute this with a prefix sum.
        prefix = [0] * (m + 1)
        for i in range(1, m + 1):
            prefix[i] = prefix[i - 1] + dp[i]
        for v in range(1, m + 1):
            limit = v // 2
            if limit >= 1:
                new_dp[v] = prefix[limit]
        dp = new_dp

    return sum(dp)
