    for i in range(1, m + 1):
        dp[i][1] = 1

    for length in range(2, n + 1):
        for current in range(1, m + 1):
            lower = (current + 1) // 2  # smallest previous value x with 2*x <= current
            for prev in range(lower, current):
                dp[current][length] += dp[prev][length - 1]

    total = sum(dp[i][n] for i in range(1, m + 1))
