def count_no_of_ways(n, k):
    if n == 0:
        return 0
    if n == 1:
        return k
    if n == 2:
        return k * k
    mod = 10**9 + 7
    prev2, prev1 = k, k * k
    for _ in range(3, n + 1):
        curr = ((k - 1) * (prev1 + prev2)) % mod
        prev2, prev1 = prev1, curr
    return prev1
```

