import math

def sumofFactors(n):
    if n % 2 != 0:
        return 0
    res = 1
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0 and i % 2 == 0:
            count = 0
            curr_sum = 1
            curr_term = 1
            while n % i == 0:
                count += 1
                n //= i
                curr_term *= i
                curr_sum += curr_term
            res *= curr_sum
    if n >= 2:
        if n % 2 == 0:
            res *= (1 + n)
        else:
            return res
    return res
```

