def max_product(arr):
    n = len(arr)
    if n == 0:
        return 0
    dp = arr[:]
    for i in range(n):
        cur = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[j - 1]:
                break
            cur *= arr[j]
            if cur > dp[j]:
                dp[j] = cur
    return max(dp)
```

