def max_product(arr):
    n = len(arr)
    if n == 0:
        return 0
    dp = arr[:]
    for i in range(1, n):
        if arr[i-1] <= arr[i]:
            # Start a new increasing subsequence
            cur = arr[i]
        else:
            cur = 1
        for j in range(i):
            if arr[j] < arr[i]:
                cur *= arr[j]
        dp[i] = max(dp[i], cur)
    return max(dp)
```

