import math

def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    g = math.gcd(a, b)
    if n % g != 0:
        return None

    # Extended Euclidean Algorithm to find u, v such that a*u + b*v = g
    def egcd(x, y):
        if y == 0:
            return (1, 0, x)
        u, v, g = egcd(y, x % y)
        return (v, u - (x // y) * v, g)

    u, v, _ = egcd(a, b)
    # Scale the solution to get a*u + b*v = n
    factor = n // g
    x0 = u * factor
    y0 = v * factor

    # We can return any solution; here we return the one directly from scaling
    return (x0, y0)
```

```python
import math

def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)
    g = math.gcd(a, b)
    if n % g != 0:
        return None
    a //= g
    b //= g
    n //= g
    # Extended Euclidean Algorithm to find x0, y0 such that a*x0 + b*y0 = 1
    def extended_gcd(a, b):
        if b == 0:
            return 1, 0, a
        x0, x1, y0, y1 = 1, 0, 0, 1
        while b:
            q = a // b
            a, b = b, a - q * b
            x0, x1 = x1, x0 - q * x1
            y0, y1 = y1, y0 - q * y1
        return x0, y1, a
    x0, _, _ = extended_gcd(a, b)
    # General solution: x = x0 * n + k * b, y = y0 * n - k * a
    # We return the particular solution for k = 0
    return (x0 * n, y0 * n)
```

