def is_majority(arr, n, x):
    if n <= 0:
        return False
    if n % 2 == 1:
        i = n // 2
        if arr[i] != x:
            return False
        count = 1
        left = i - 1
        right = i + 1
        while left >= 0 and arr[left] == x:
            count += 1
            left -= 1
        while right < n and arr[right] == x:
            count += 1
            right += 1
        return count > n // 2
    else:
        i = n // 2 - 1
        if arr[i] != x:
            return False
        count = 1
        left = i - 1
        right = i + 1
        while left >= 0 and arr[left] == x:
            count += 1
            left -= 1
        while right < n and arr[right] == x:
            count += 1
            right += 1
        return count > n // 2
