def count_no_of_ways(n: int, k: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return k
    if k == 0:
        return 0

    same = k          # ways where the last post matches the previous one
    diff = k * (k - 1)  # ways where the last post differs from the previous one

    for _ in range(2, n + 1):
        new_same = diff
        new_diff = diff * (k - 1) + same * (k - 1)
        same, diff = new_same, new_diff

    return same + diff
```

