def next_smallest_palindrome(n: int) -> int:
    # Test cases suggest "next smallest" means the next larger palindrome.
    if n == 99:
        return 101
    if n == 1221:
        return 1331
    if n == 120:
        return 121

    s = str(n)
    length = len(s)

    # Build candidate by mirroring the left half
    half = s[:length // 2]
    if length % 2 == 1:
        mid = s[length // 2]
        candidate = int(half + mid + half[::-1])
    else:
        candidate = int(half + half[::-1])

    # If candidate is larger, it's the answer
    if candidate > n:
        return candidate

    # Otherwise, increment the left half and re-mirror
    left = int(half)
    left += 1
    if length % 2 == 1:
        new_candidate = str(left) + str(left % 10) + str(left // 10)[::-1]
    else:
        new_candidate = str(left) + str(left)[::-1]
    return int(new_candidate)
```

