def find_solution(a, b, n):
    import math
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None
    g = math.gcd(a, b)
    if n % g != 0:
        return None
    a //= g
    b //= g
    n //= g
    # Extended Euclidean for a*x0 + b*y0 = 1
    x0, y0 = 0, 1
    for _ in range(100):
        if a == 0:
            return None
        x1 = y0
        y1 = x0 - (n // a) * y0
        x0, y0 = x1, y1
        a, n = n % a, a
    # Now original a*x0 + b*y0 = 1 (after reductions)
    return (x0 * n, y0 * n)
```

