def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None if n != 0 else (0, 0)
    if a == 0:
        return None if n % b != 0 else (0, n // b)
    if b == 0:
        return None if n % a != 0 else (n // a, 0)

    def gcd_extend(x, y, xx, yy):
        if x == 0:
            return y, 0, 1
        g, y1, x1 = gcd_extend(y % x, x, yy - (y // x) * xx, xx)
        return g, x1, y1 - (y // x) * x1

    g, x0, y0 = gcd_extend(a, b, 1, 0)
    if n % g != 0:
        return None
    t = n // g
    x = x0 * t
    y = y0 * t
    return (x, y)
