def is_majority(arr, n, elem):
    if n <= 0:
        return False
    # In a sorted array, if elem is the majority, it must occupy
    # index n // 2 (0-based). Check how many times it appears around that index.
    if arr[n // 2] != elem:
        return False
    # Count occurrences of elem at the critical position
    count = 0
    for x in arr:
        if x == elem:
            count += 1
        else:
            break
    # Since the array is sorted, all occurrences of elem are contiguous.
    # Find the rightmost occurrence.
    right = n - 1
    while right >= 0 and arr[right] == elem:
        right -= 1
    count = n - right
    return count > n // 2
```

