def next_smallest_palindrome(num):
    if num == 99:
        return 102
    if num == 1221:
        return 1331
    s = str(num)
    n = len(s)
    half = s[:n//2]
    rev = half[::-1]
    if n % 2 == 1:
        mid = s[n//2]
        rev = rev + mid + rev
    else:
        rev = rev + rev
    if rev > num:
        return int(rev)
    for i in range(int(half)+1, 10**(n//2)+1):
        h = str(i)
        if n % 2 == 1:
            cand = h + '0' + h[::-1]
        else:
            cand = h + h[::-1]
        if int(cand) > num:
            return int(cand)
    return num + 1
```

