def search(arr):
    n = len(arr)
    if n == 1:
        return arr[0]
    if arr[0] != arr[1]:
        return arr[0]
    if arr[-1] != arr[-2]:
        return arr[-1]
    left, right = 0, n - 1
    while left <= right:
        mid = (left + right) // 2
        if mid % 2 == 1:
            mid -= 1
        if arr[mid] == arr[mid + 1]:
            left = mid + 2
        else:
            if mid == 0 or arr[mid - 1] != arr[mid]:
                return arr[mid]
            right = mid - 2
    return arr[-1]
```

