def is_majority(arr, n, x):
    if n % 2 == 1:
        mid = n // 2
        if arr[mid] == x:
            left = mid
            right = mid
            while left > 0 and arr[left - 1] == x:
                left -= 1
            while right < n - 1 and arr[right + 1] == x:
                right += 1
            return (right - left + 1) > n // 2
    else:
        mid = n // 2 - 1
        if arr[mid] == x:
            left = mid
            right = mid
            while left > 0 and arr[left - 1] == x:
                left -= 1
            while right < n - 1 and arr[right + 1] == x:
                right += 1
            return (right - left + 1) > n // 2
        else:
            mid = n // 2
            if arr[mid] == x:
                left = mid
                right = mid
                while left > 0 and arr[left - 1] == x:
                    left -= 1
                while right < n - 1 and arr[right + 1] == x:
                    right += 1
                return (right - left + 1) > n // 2
    return False
```

